from .testline_info import TestlineInfo


class info(object):

    @staticmethod
    def has_airphone(tl):
        """
        Checks if `Airphone` object is available within `TestLine` object (availability of `Simulator` object is not verified!)
        :return: True or False
        """
        return TestlineInfo.has_airphone(tl)

    @staticmethod
    def has_cus(tl):
        """
        Checks if `CUS` object is available within `TestLine` object (availability of `Simulator` object is not verified!)
        :return: True or False
        """
        return TestlineInfo.has_cus(tl)

    @staticmethod
    def has_simulator(tl):
        """
        Checks if any object type Simulator/Airphone/CUS is available within `TestLine` object
        :return: True or False
        """
        return TestlineInfo.has_simulator(tl)

    @staticmethod
    def has_prisma(tl):
        """
        Checks if object Prisma is in testline configuration object
        :return: True or False
        """
        return TestlineInfo.has_prisma(tl)

    @staticmethod
    def has_tm500(tl):
        """
        Checks if object TM500 (ViaVi) is in testline configuration object
        :return: True or False
        """
        return TestlineInfo.has_tm500(tl)

    @staticmethod
    def has_enb(tl):
        """
        Checks if there is any enb object is in testline configuration object
        :return: True or False
        """
        return TestlineInfo.has_enb(tl)

    @staticmethod
    def get_x2_link_addr(tl):
        """
        Gets ip address of x2 from testline configuration object in enb
        :return: str with ip address
        :raises: AttributeError if no enb object in testline.enbs
        """
        return TestlineInfo.get_x2_link_addr(tl)

    @staticmethod
    def has_epcsim(tl):
        """
        Checks if core is EpcSim object in testline configuration object
        :return: True or False
        """
        return TestlineInfo.has_epcsim(tl)

    @staticmethod
    def has_lteemu_core(tl):
        """
        Checks if core is LteemuCore object in testline configuration object
        :return: True or False
        """
        return TestlineInfo.has_lteemu_core(tl)

    @staticmethod
    def has_prisma_core(tl):
        """
        Checks if core is PrismaCore object in testline configuration object
        :return: True or False
        """
        return TestlineInfo.has_prisma_core(tl)

    @staticmethod
    def has_cloudBts(tl):
        """
        Checks if CloudBts object in testline configuration object
        :return: True or False
        """
        return TestlineInfo.has_cloudBts(tl)

    @staticmethod
    def is_backhaul_ipv6(tl):
        """
        Checks if backhaul site oam ip of first gNb is in IPv6 format
        :return: True or False
        """
        return TestlineInfo.is_backhaul_ipv6(tl)

    @staticmethod
    def get_vnf_prefix(tl):
        """
        Gets default vnf prefix of first flavor in cloud deployment
        :return: str with prefix
        """
        return TestlineInfo.get_vnf_prefix(tl)

    @staticmethod
    def get_number_of_du(tl):
        """
        Gets number of du in testline
        :return: int with du number
        """
        return TestlineInfo.get_number_of_du(tl)

    @staticmethod
    def get_du_list(tl):
        """
        Gets list with dus of first gNb in testline configuration object
        :return: list with DU objects
        """
        return TestlineInfo.get_du_list(tl)

    @staticmethod
    def get_core(tl):
        """
        Gets core object from testline configuration object
        :return: Core object
        :raises: AttributeError if core is None
        """
        return TestlineInfo.get_core(tl)

    @staticmethod
    def get_mme_ip(tl):
        """
        Gets mme_ip of Core from testline configuration object.
        :return: string with mme_ip
        :raises: AttributeError if core is None
        """
        return TestlineInfo.get_mme_ip(tl)

    @staticmethod
    def get_mnc(tl):
        """
        Gets mnc of Core from testline configuration object.
        :return: string with mme_ip
        :raises: AttributeError if core is None
        """
        return TestlineInfo.get_mnc(tl)

    @staticmethod
    def get_mcc(tl):
        """
        Gets get_mcc of Core from testline configuration object.
        :return: string with mme_ip
        :raises: AttributeError if core is None
        """
        return TestlineInfo.get_mcc(tl)

    @staticmethod
    def get_nrarfcns(tl):
        """
        Based on radio type of RU, gets its frequency and calculates on basis of 3GPP formula proper nrarfcn value
        :return: dict where key is string with du number and value is int with nrarfcn, eg. {'NRDU-1': 636666}
        :raises: FrequencyNotSupported if radio has frequency over 100 GHz or below 0
        :raises BandNotSupported if radio is FDD or maps to band that 3GPP gives no data about
        """
        return TestlineInfo.get_nrarfcns(tl)

    @staticmethod
    def get_airscale_endpoint(airscale):
        """
        Gets SSH connection details of hardware devices for specific Airscale

        :param airscale: place fo which endpoint is returned
        :return: SSH connection details of airscale's hardware
        """
        return TestlineInfo.get_airscale_endpoint(airscale)

    @staticmethod
    def get_signal_analyzer(ru):
        """
        Gets signal analyzer configuration object from given RU configuration object.
        :param ru: radio configuration object from which signal analyzer will be taken
        :type ru: RU
        :return: configuration object of signal analyzer connected to RU; None if signal analyzer is absent
        :rtype: SignalAnalyzer
        """
        return TestlineInfo.get_signal_analyzer(ru)

    @staticmethod
    def get_ru_duplex_method(radio_type, fh_interface=None):
        """
        Gets certain RU duplex method for given RU type (RU name) according to records in
        taf/config/testline/info/data/ru_list.csv. If RU is not found exception is thrown.
        :param radio_type: RU name (radio_type from RU object in taf.config.testline) i.e. FXDB, AHEGA
        :type radio_type: str
        :param fh_interface: FH interface of radio, eg: CPRI/eCPRI. Some of Radio Type has multiple FH interfaces.
                             In this case radio_type and fh_interface
                             should be provided to get the correct duplex method.
        :type fh_interface: str
        :return: duplex method (FDD or TDD or FDD+TDD)
        :rtype: str
        """
        return TestlineInfo.get_ru_duplex_method(radio_type, fh_interface)

    @staticmethod
    def get_ru_password(username='serviceuser', **kwargs):
        """
        Gets password for given SW Line/radio_type and user from ru_credentials.csv file. One of the parameters
        'radio_sw_line' or 'radio_type' must be provided.
        :param username: user for which password is returned(rfsw or serviceuser)
        :param kwargs: additional parameters
            by_sw_line: SW Line of radio
            by_radio_type: type of radio, ignored when by_sw_line is defined
            fh_interface: FH interface of radio eg: CPRI/eCPRI, ignored when by_sw_line is defined.
                          Some of Radio Type has multiple FH interfaces. In this case
                          by_radio_type and fh_interface should be provided to get the correct password.
        :return: password for given SW Line and user
        """

        return TestlineInfo.get_ru_password(username, **kwargs)

    @staticmethod
    def get_ru_sw_line(radio_type, fh_interface=None):
        """
        Gets SW Line for given RU type (RU name) according to records in
        taf/config/testline/info/data/ru_list.csv. If RU is not found exception is thrown.
        :param radio_type: RU name (radio_type from RU object in taf.config.testline) i.e. FXDB, AHEGA
        :param fh_interface: FH interface of radio, eg: CPRI/eCPRI. Some of Radio Type has multiple FH interfaces.
                            In this case radio_type and fh_interface should be provided to get the correct SW Line.
        :type radio_type: str
        :return: SW Line of the RU
        :rtype: str
        """
        return TestlineInfo().get_ru_sw_line(radio_type, fh_interface)
